import{_ as a,o as t,c as o,a2 as l}from"./chunks/framework.CqGPl1zp.js";const r="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/IDEA%E9%85%8D%E7%BD%AE%E7%83%AD%E5%8A%A0%E8%BD%BD.png",p="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/IDEA%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD.png",s="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/JRebel%E4%B8%8B%E8%BD%BD.png",i="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/JRebel%E5%AE%89%E8%A3%85.png",n="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/JRebel%E6%BF%80%E6%B4%BB.png",d="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/JRebel%E7%A6%BB%E7%BA%BF.png",c="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/JRebel%E5%90%AF%E5%8A%A8%E9%A1%B9%E7%9B%AE.png",m="/newx-doc/img/%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD/JRebel%E4%BB%A3%E7%A0%81%E7%83%AD%E5%8A%A0%E8%BD%BD.png",D=JSON.parse('{"title":"代码热加载","description":"","frontmatter":{},"headers":[],"relativePath":"dev-hot-swap.md","filePath":"dev-hot-swap.md","lastUpdated":null}'),E={name:"dev-hot-swap.md"};function b(h,e,A,g,u,B){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="代码热加载" tabindex="-1">代码热加载 <a class="header-anchor" href="#代码热加载" aria-label="Permalink to &quot;代码热加载&quot;">​</a></h1><p>在日常开发中，我们需要经常修改 Java 代码，手动重启项目，查看修改后的效果。如果在项目小时，重启速度比较快，等待的时间是较短的。但是随着项目逐渐变大，重启的速度变慢，等待时间 1-2 min 是比较常见的。</p><p>这样就导致我们开发效率降低，影响我们的下班时间，哈哈哈~</p><p>那么是否有方式能够实现，在我们修改完 Java 代码之后，能够不重启项目呢？答案是有的，通过 <strong>代码热加载</strong> 的方式。实现方案有三种：</p><ol><li>spring-boot-devtools【不推荐】</li><li>IDEA 自带 HowSwap 功能【推荐】</li><li>JRebel 插件【最推荐】</li></ol><h2 id="_1-spring-boot-devtools" tabindex="-1">1. spring-boot-devtools <a class="header-anchor" href="#_1-spring-boot-devtools" aria-label="Permalink to &quot;1. spring-boot-devtools&quot;">​</a></h2><p><a href="https://docs.spring.io/spring-boot/docs/current/reference/htmlsingle/#using.running-your-application.hot-swapping" target="_blank" rel="noreferrer">spring-boot-devtools</a> 是 Spring Boot 提供的开发者工具，它会监控当前应用所在的 classpath 下的文件发生变化，进行<strong>自动重启</strong>。</p><p>devtools 存在重启速度较慢的问题，所以不推荐！</p><h2 id="_2-idea-自带-howswap-功能" tabindex="-1">2. IDEA 自带 HowSwap 功能 <a class="header-anchor" href="#_2-idea-自带-howswap-功能" aria-label="Permalink to &quot;2. IDEA 自带 HowSwap 功能&quot;">​</a></h2><p>该功能是 IDEA Ultimate 旗舰版的专属功能，不支持 IDEA Community 社区版。</p><h3 id="_2-1-如何使用" tabindex="-1">2.1 如何使用 <a class="header-anchor" href="#_2-1-如何使用" aria-label="Permalink to &quot;2.1 如何使用&quot;">​</a></h3><p>① 设置 Spring Boot 启动类，开启 HotSwap 功能。如下图所示：</p><p><img src="'+r+'" alt="IDEA 配置热加载"></p><p>② Debug 运行该启动类，等待项目启动完成。</p><p>③ 每次修改 Java 代码后，点击左下角的「热加载」按钮，即可实现代码热加载。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-system-api 和 yudao-module-system-biz 子模块，代码直接合并到 yudao-module-system 模块的 src 目录下，更适合单体项目</p><p><img src="'+p+'" alt="IDEA 代码热加载"></p><h3 id="_2-2-存在问题" tabindex="-1">2.2 存在问题 <a class="header-anchor" href="#_2-2-存在问题" aria-label="Permalink to &quot;2.2 存在问题&quot;">​</a></h3><p>IDEA 自带 HowSwap 功能，支持比较有限，很多修改都不支持。例如说：</p><ul><li>只能增加方法或字段但不可以减少方法或字段</li><li>只能增加可见性不能减少</li><li>只能维持已有方法的签名而不能修改等等。</li></ul><p>你可以认为，只支持方法内的代码修改热加载。</p><p>如果想要相对完美的方案，建议使用 JRebel 插件。</p><h2 id="_3-jrebel-插件【最推荐】" tabindex="-1">3. JRebel 插件【最推荐】 <a class="header-anchor" href="#_3-jrebel-插件【最推荐】" aria-label="Permalink to &quot;3. JRebel 插件【最推荐】&quot;">​</a></h2><p>JRebel 插件是目前最好用的热加载插件，它支持 IDEA Ultimate 旗舰版、Community 社区版。</p><h3 id="_3-1-如何安装" tabindex="-1">3.1 如何安装 <a class="header-anchor" href="#_3-1-如何安装" aria-label="Permalink to &quot;3.1 如何安装&quot;">​</a></h3><p>友情提示：不同的 JetBrains 版本，JRebel 插件的激活方式不同：</p><ul><li>2022.4.1 版本：阅读本文即可。</li><li>2024.1.2 版本：<a href="https://www.cnblogs.com/Flat-White/p/18090651" target="_blank" rel="noreferrer">https://www.cnblogs.com/Flat-White/p/18090651</a> （别的版本，应该也可以）</li></ul><hr><p>最近主要用 2025.2 版本，即可方式如下：</p><ul><li>JRebel &amp;Xrebel 激活码 <code>http://42.51.34.83:8877/54502c46-40e5-4199-9acf-45983c2f1882</code></li><li>【腾讯文档】JRebel &amp;Xrebel 激活步骤 <a href="https://docs.qq.com/doc/DQ29MRHZweExGSkhq" target="_blank" rel="noreferrer">https://docs.qq.com/doc/DQ29MRHZweExGSkhq</a></li></ul><p>如果 GUID 过期，可以试试 <a href="https://www.guidgen.com/" target="_blank" rel="noreferrer">https://www.guidgen.com/</a> 去生成！！！</p><p>① 点击 <a href="https://plugins.jetbrains.com/plugin/4441-jrebel-and-xrebel/versions" target="_blank" rel="noreferrer">https://plugins.jetbrains.com/plugin/4441-jrebel-and-xrebel/versions</a> 地址，必须下载 <strong>2022.4.1</strong> 版本。如下图所示：</p><p><img src="'+s+'" alt="JRebel 下载"></p><p>② 打开 [Preference -&gt; Plugins] 菜单，点击「Install Plugin from Disk...」按钮，选择刚下载的 JRebel 插件的压缩包。如下图所示：</p><p><img src="'+i+'" alt="JRebel 安装"></p><p>安装完成后，需要重启 IDEA 生效。</p><p>③ 打开 [Preference -&gt; JRebel &amp; XRebel] 菜单，输入 GUID address 为 <code>https://jrebel.qekang.com/1e67ec1b-122f-4708-87d0-c1995dc0cdaa</code> ，邮件随便写，完成 JRebel 的激活。如下图所示：</p><p><img src="'+n+'" alt="JRebel 激活"></p><p>之后，点击「Work Offline」按钮，设置 JRebel 为离线，避免因为网络问题导致激活失效。如下图所示：</p><p><img src="'+d+'" alt="JRebel 离线"></p><h3 id="_3-2-如何使用" tabindex="-1">3.2 如何使用 <a class="header-anchor" href="#_3-2-如何使用" aria-label="Permalink to &quot;3.2 如何使用&quot;">​</a></h3><p>① 点击「Debug With JRebel」按钮，使用 JRebel 启动项目。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-system-api 和 yudao-module-system-biz 子模块，代码直接合并到 yudao-module-system 模块的 src 目录下，更适合单体项目</p><p><img src="'+c+'" alt="JRebel 启动项目"></p><p>② 每次修改 Java 代码后，点击左下角的「热加载」按钮，即可实现代码热加载。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-system-api 和 yudao-module-system-biz 子模块，代码直接合并到 yudao-module-system 模块的 src 目录下，更适合单体项目</p><p><img src="'+m+'" alt="JRebel 代码热加载"></p><h3 id="_3-3-补充说明" tabindex="-1">3.3 补充说明 <a class="header-anchor" href="#_3-3-补充说明" aria-label="Permalink to &quot;3.3 补充说明&quot;">​</a></h3><p>① mybatis plus 如何热部署？</p><p>需要安装 <a href="https://plugins.jetbrains.com/plugin/12682-jrebel-mybatisplus-extension" target="_blank" rel="noreferrer">https://plugins.jetbrains.com/plugin/12682-jrebel-mybatisplus-extension</a> 插件。</p>',50)])])}const w=a(E,[["render",b]]);export{D as __pageData,w as default};
